// P15 (Save45): the four P15 roots are V45-only, so a genuine V13 file never carried
// them. They strip only while every root is empty: a P15 native row or a spent
// allocator is real authority and refuses, as with the guarded roots below. The RED
// helper's one list names the roots, so a later P15 root joins this guard when that
// list grows. A state from an older era carries no root, which reads as empty.
if (p15Rows(state).length > 0 || (state.p15Sequence?.next ?? 1) !== 1) {
  throw new Error('V13 twin cannot discard P15 authority')
}
const raw = stripP15(clone(state))

// 1361-N S1: 44 -> 45 (the four P15 roots); validateSaveV45 (save.ts:10962)
// is live and validateSaveV44 (:10822) is frozen.
validateSaveV45: (input: unknown) => Save38 }

// 1361-N S1/S4: the live envelope became V45 (the four P15 roots), so
// validateSaveV39 validates it with validateSaveV45 and convertV45ToV44
// leads the chain, one era later again.

// 1361-N S5: Save45 (convertV44ToV45, save.ts:10980-10984) adds the four P15 roots, empty, at the
// save's own week and back-fills nothing; a genuine V37 old.state never carried them. The literals
// are this file's own expectation: production's initialP15Roots never defines it (1361-F7 ruling 3).
function withEmptyP15Roots<T extends object>(state: T, week: number): T {
  return { ...state,
    powerRanking: { version: 1, recordedFromWeek: week, snapshots: [] },
    p15Sequence: { version: 1, next: 1 },
    sharedMarket: { version: 1, recordedFromWeek: week, assessments: [] },
    campaignLegacy: { version: 1, recordedFromWeek: week, official: null, endOfRun: null } }
}
